# Check item_name variable exists and is correct type
if 'item_name' not in locals():
    raise AssertionError('Missing item_name variable')

if not isinstance(item_name, str):
    raise AssertionError(f'item_name should be a string, got {type(item_name).__name__}')

if item_name is None:
    raise AssertionError('item_name is still None. Replace it with a string value!')

print('TEST_PASSED: item_name is a string')

# Check stock_count variable
if 'stock_count' not in locals():
    raise AssertionError('Missing stock_count variable')

if not isinstance(stock_count, int) or isinstance(stock_count, bool):
    raise AssertionError(f'stock_count should be an integer, got {type(stock_count).__name__}')

if stock_count is None:
    raise AssertionError('stock_count is still None. Replace it with an integer value!')

print('TEST_PASSED: stock_count is an integer')

# Check item_price variable
if 'item_price' not in locals():
    raise AssertionError('Missing item_price variable')

if not isinstance(item_price, float):
    raise AssertionError(f'item_price should be a float (decimal number), got {type(item_price).__name__}')

if item_price is None:
    raise AssertionError('item_price is still None. Replace it with a float value!')

print('TEST_PASSED: item_price is a float')

# Check is_available variable
if 'is_available' not in locals():
    raise AssertionError('Missing is_available variable')

if not isinstance(is_available, bool):
    raise AssertionError(f'is_available should be a boolean (True or False), got {type(is_available).__name__}')

if is_available is None:
    raise AssertionError('is_available is still None. Replace it with True or False!')

print('TEST_PASSED: is_available is a boolean')
